-- Store the chunks produced from each RAG document.
CREATE TABLE IF NOT EXISTS rag_document_chunks (
    -- Unique identifier generated by the application for each chunk.
    id UUID PRIMARY KEY,

    -- Parent document. Removing the document also removes all of its chunks.
    document_id UUID NOT NULL
        REFERENCES rag_documents(id)
        ON DELETE CASCADE,

    -- Version of the parent document from which this chunk was generated.
    document_version INTEGER NOT NULL,

    -- Zero-based position of the chunk in the parent document.
    chunk_index INTEGER NOT NULL
        CHECK (chunk_index >= 0),

    -- Original text retained for prompt context and source citations.
    content TEXT NOT NULL
        CHECK (btrim(content) <> ''),

    -- Semantic vector used by pgvector similarity search.
    embedding vector(1536) NOT NULL,

    -- Identifies the embedding model/vector space used for this chunk.
    embedding_profile VARCHAR(160) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),

    -- A document can contain only one chunk at a given position.
    CONSTRAINT ux_rag_document_chunks_document_index
        UNIQUE (document_id, chunk_index)
);

-- Speeds up loading, replacing, and deleting all chunks of one document.
CREATE INDEX IF NOT EXISTS ix_rag_document_chunks_document
    ON rag_document_chunks(document_id);

-- Speeds up filtering to vectors created by the same embedding model.
CREATE INDEX IF NOT EXISTS ix_rag_document_chunks_profile
    ON rag_document_chunks(embedding_profile);

-- Enables efficient cosine-distance nearest-neighbour searches.
CREATE INDEX IF NOT EXISTS ix_rag_document_chunks_embedding
    ON rag_document_chunks
    USING hnsw (embedding vector_cosine_ops);
